def verify(tasks):
    for t in tasks: assert os.path.exists(t['model']), t['model']; assert sha(t['model']) == t['model_sha256'], t['name']; assert sha(t['model'] + '.evid') == t['evid_sha256'], t['name']; t['verified_now'] = True
    return tasks

