def holdout(root):
    require_local_source(root)
    import research.campaigns.hp.dense_gen as DG
    fr = json.load(open(os.path.join(RD, 'FREEZE.json'))); head = git(root, 'rev-parse', 'HEAD'); assert head == fr['code']['commit'], 'holdout must be generated at the frozen commit (%s != %s)' % (head[:9], fr['code']['commit'][:9])
    fm = DG.generate('eval5', os.path.join(RD, 'inputs_fresh')); om = DG.generate('oracle5', os.path.join(RD, 'oracle', 'inputs_fresh'))                    # the ONLY generations of this round (after the second freeze)
    def mk(m, panel, exposure, extra=None): return dict(dict(name=m['name'], panel=panel, exposure=exposure, topology=m['topology'], n=m['n'], card=m['card'], scale=m['scale'], model=m['model'], model_sha256=m['model_sha256'], evid_sha256=m['evid_sha256'], K=m['K'], edges=m['edges'], cycle_rank=m['cycle_rank'], degree=m['degree'], graph_attempts_rejected=m['graph_attempts_rejected'], exact_profile_reduction=m['exact_profile_reduction'], dynamic_range=m['dynamic_range'], seed=m['seed'], tag=m['tag']), **(extra or {}))
    fresh = verify([mk(m, 'fresh_8', 'fresh (DGP5-EVAL5; generated after the second freeze)') for m in fm]); fresh_oracle = verify([mk(m, 'oracle_fresh_4', 'fresh oracle (DGP5-ORACLE5; generated after the second freeze; oracle only)', dict(fine_states=m['card'] ** m['n'])) for m in om])
    for t in fresh: t['name_generated'] = t['name']; t['name'] = t['name'] + '__eval5'
    for t in fresh_oracle: t['name_generated'] = t['name']; t['name'] = t['name'] + '__oracle5'
    oracle24 = verify([dict(t, exposure='exposed to the oracle (DGP2-ORACLE-EVAL-1 / DGP4-ORACLE4; bytes verified)') for t in json.load(open(os.path.join(DGP4, 'ORACLE_MANIFEST.json')))['tasks']]); assert len(oracle24) == 24
    main4 = json.load(open(os.path.join(DGP4, 'MAIN_MANIFEST.json')))['tasks']; exposed52 = verify([dict(t, exposure='exposed (the 52 DGP4 main inputs: 44 + 8 EVAL-4 as __eval4; original bytes)', panel_dgp4=t.get('panel'), panel='exposed_52') for t in main4]); assert len(exposed52) == 52 and len({t['name'] for t in exposed52}) == 52
    pres18 = verify([dict(t, exposure='exposed (USR1 / DGP1 preservation)') for t in json.load(open(os.path.join(DGP1, 'PRESERVATION_18_MANIFEST.json')))['tasks']]); pres13 = verify([dict(t, exposure='exposed (accepted preservation panel)') for t in json.load(open(os.path.join(DGP1, 'PRESERVATION_13_MANIFEST.json')))['tasks']])
    diag = [t for t in exposed52 if t['name'] in DIAG_NAMES]; assert len(diag) == 8, [t['name'] for t in diag]
    main = exposed52 + fresh; assert len(main) == 60 and len({(t['model_sha256'], t['evid_sha256']) for t in main}) == 60
    for name, tasks in (('ORACLE_MANIFEST', oracle24 + fresh_oracle), ('FRESH_MANIFEST', fresh), ('MAIN_MANIFEST', main), ('PRESERVATION_18_MANIFEST', pres18), ('PRESERVATION_13_MANIFEST', pres13), ('DIAG_MANIFEST', diag)): json.dump(dict(tasks=tasks, code_commit=head, freeze_sha256=sha(os.path.join(RD, 'FREEZE.json'))), open(os.path.join(RD, name + '.json'), 'w'), indent=1)
    allm = dict(experiment='DGP5_JOINT_CONSTRUCTION', utc=time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime()), code_commit=head, freeze_sha256=sha(os.path.join(RD, 'FREEZE.json')), generated_manifests=[os.path.join(RD, 'inputs_fresh', 'GENERATED_MANIFEST.json'), os.path.join(RD, 'oracle', 'inputs_fresh', 'GENERATED_MANIFEST.json')],
                panels=dict(oracle_24=oracle24, oracle_fresh_4=fresh_oracle, oracle_28=oracle24 + fresh_oracle, fresh_8=fresh, exposed_52=exposed52, main_60=main, preservation_18=pres18, preservation_13=pres13, diag_8=[t['name'] for t in diag], replay_anchors=dict(exposed_7=REPLAY_EXPOSED, fresh_4=[t['name'] for t in fresh_oracle])),
                exposure_labels=dict(fresh='generated after the second freeze (DGP5-EVAL5); production arms', fresh_oracle='generated after the second freeze (DGP5-ORACLE5); oracle only', exposed='bytes identical to DGP1 / DGP2 / DGP3 / DGP4 / USR1 / accepted-panel inputs (sha256 verified now)', oracle='DGP2 / DGP4 oracle inputs (exposed to oracle calculations only; never production arms)'))
    json.dump(allm, open(os.path.join(RD, 'MODEL_MANIFEST.json'), 'w'), indent=1); print('oracle', len(oracle24), '+', len(fresh_oracle), 'fresh', len(fresh), 'exposed', len(exposed52), 'main', len(main), 'pres', len(pres18), len(pres13), 'diag', len(diag)); print('fresh seeds', [(t['name'], t['seed']) for t in fresh]); print('fresh oracle', [(t['name'], t['seed'], t['exact_profile_reduction'].get('variables_reduced')) for t in fresh_oracle])

